-- Caller owns BEGIN/ROLLBACK. Only synthetic fixtures; never dispatch a message.
set local lock_timeout='3s';set local statement_timeout='45s';
create temporary table record_email_assertions(label text);
create function pg_temp.record_email_check(ok boolean,label text)returns void language plpgsql as $$begin
 if ok is distinct from true then raise exception 'Email history assertion failed: %',label;end if;
 insert into pg_temp.record_email_assertions values(label);
end$$;
do $test$
declare party uuid:=gen_random_uuid();site uuid:=gen_random_uuid();job uuid:=gen_random_uuid();quote uuid:=gen_random_uuid();invoice uuid:=gen_random_uuid();change_order uuid:=gen_random_uuid();creator uuid:=gen_random_uuid();actor uuid;role_name text;column_name text;target uuid;source_table text;p1 uuid;p2 uuid;selected uuid;v integer;source_visible integer;denied boolean;before_state jsonb;after_state jsonb;settings_before jsonb;delivery uuid:=gen_random_uuid();unrecorded uuid:=gen_random_uuid();
begin
 select to_jsonb(s)into settings_before from public.communication_settings s where singleton;
 perform pg_temp.record_email_check((settings_before->>'automated_sending_enabled')::boolean=false and(settings_before->>'appointment_change_notices_enabled')::boolean=false,'Sending and notices remain OFF');
 perform pg_temp.record_email_check((select relrowsecurity from pg_class where oid='public.email_events'::regclass),'Email history RLS enabled');
 perform pg_temp.record_email_check(not has_table_privilege('authenticated','app_private.outbound_deliveries','SELECT'),'Browser roles cannot read frozen delivery bodies');
 insert into public.roles(name)values('owner'),('admin'),('estimator'),('payroll_admin'),('crew'),('customer'),('property_manager')on conflict(name)do nothing;
 insert into auth.users(id,email)values(creator,'record-email-creator-'||creator||'@example.invalid');
 insert into public.customers(id,display_name,email)values(party,'Synthetic email-history customer','history@example.invalid');
 insert into public.service_locations(id,customer_id,street,city,state)values(site,party,'1 Synthetic Lane','Fredericksburg','VA');
 insert into public.jobs(id,customer_id,service_location_id,status)values(job,party,site,'scheduled');
 insert into public.quotes(id,customer_id,service_location_id,quote_number,status,subtotal_cents,total_cents)values(quote,party,site,'SYNTHETIC-MAIL-'||quote,'sent',10000,10000);
 insert into public.invoices(id,customer_id,service_location_id,invoice_number,status,subtotal_cents,total_cents,balance_due_cents)values(invoice,party,site,'SYNTHETIC-MAIL-'||invoice,'sent',10000,10000,10000);
 insert into public.change_orders(id,change_order_number,source_quote_id,job_id,customer_id,service_location_id,created_by_user_id,title,status)values(change_order,'SYNTHETIC-MAIL-'||change_order,quote,job,party,site,creator,'Synthetic additional work','sent');
 for column_name,target in select * from(values('related_quote_id',quote),('related_invoice_id',invoice),('related_change_order_id',change_order))r loop
  execute format('insert into public.email_events(%I,recipient_email,subject,email_type,status,delivery_status,created_at,sent_at,error_message)select $1,''history@example.invalid'',''Synthetic recorded email ''||n,''invoice'',case when n%%2=0 then ''sent''else ''failed''end,case when n%%2=0 then case when n%%8=0 then ''delayed''else ''delivered''end when n%%7=0 then null when n%%5=0 then ''bounced''else ''failed''end,''2026-10-24T12:00:00Z''::timestamptz+(n/2)*interval''1 microsecond'',case when n%%2=0 and n%%6<>0 then ''2026-10-24T12:00:00Z''::timestamptz+n*interval''1 microsecond''else null end,case when n%%7=0 and n%%2=1 then ''provider_outcome_unknown''else null end from generate_series(1,2106)n',column_name)using target;
  p1:=gen_random_uuid();p2:=gen_random_uuid();execute format('insert into public.email_events(id,%I,recipient_email,subject,email_type,status,created_at)values($1,$3,''history@example.invalid'',''Synthetic tied email'',''invoice'',''sent'',''2026-10-24T12:00:01Z''),($2,$3,''history@example.invalid'',''Synthetic tied email'',''invoice'',''sent'',''2026-10-24T12:00:01Z'')',column_name)using p1,p2,target;
  execute format('select count(*)from public.email_events where %I=$1',column_name)into v using target;perform pg_temp.record_email_check(v=2108,column_name||': complete count beyond REST preview limits');
  execute format('select count(*)from public.email_events where %I=$1 and(status=''failed''or delivery_status in(''delayed'',''failed'',''bounced'',''complained'',''suppressed'')or error_message=''provider_outcome_unknown'')',column_name)into v using target;perform pg_temp.record_email_check(v=1316,column_name||': attention includes failed, delayed and unknown outcomes');
  execute format('select id from public.email_events where %I=$1 order by created_at desc,id asc limit 1',column_name)into selected using target;perform pg_temp.record_email_check(selected=least(p1,p2),column_name||': stable UUID ordering for timestamp ties');
  execute format('select count(*)from(select id from public.email_events where %I=$1 order by created_at desc,id asc offset 30 limit 30)x',column_name)into v using target;perform pg_temp.record_email_check(v=30,column_name||': second page remains scoped');
  execute format('select count(*)from(select id from public.email_events where %I=$1 order by created_at desc,id asc offset 2100 limit 30)x',column_name)into v using target;perform pg_temp.record_email_check(v=8,column_name||': exact last-page remainder');
  execute format('select count(*)from public.email_events where %I=$1 and status=''sent''and sent_at is null',column_name)into v using target;perform pg_temp.record_email_check(v>0,column_name||': unknown actual send dates retained');
  execute format('select count(*)from public.email_events where %I=$1 and error_message=''provider_outcome_unknown''',column_name)into v using target;perform pg_temp.record_email_check(v>0,column_name||': uncertain records retained');
 end loop;
 insert into app_private.outbound_deliveries(id,business_key,provider_key,payload,payload_hash,context,source_snapshot,state,delivery_status,repair_state)
 values(delivery,'synthetic-history:'||delivery,'synthetic-history:'||delivery,'{"to":["history@example.invalid"],"subject":"Synthetic invoice","html":"PRIVATE_SYNTHETIC_BODY"}',repeat('a',64),jsonb_build_object('kind','invoice','invoice_id',invoice),'{}','accepted','delivered','complete'),
 (unrecorded,'synthetic-history:'||unrecorded,'synthetic-history:'||unrecorded,'{"to":["history@example.invalid"],"subject":"Synthetic unrecorded request","html":"PRIVATE_SYNTHETIC_BODY"}',repeat('b',64),jsonb_build_object('kind','invoice','invoice_id',invoice),'{}','unknown','pending','needs_review');
 update public.email_events set outbound_delivery_id=delivery where id=(select id from public.email_events where related_invoice_id=invoice order by created_at desc,id limit 1);
 perform pg_temp.record_email_check((select count(*)from public.email_events where outbound_delivery_id=delivery)=1,'One recorded row links to one durable delivery');
 perform pg_temp.record_email_check(not exists(select 1 from public.email_events where outbound_delivery_id=unrecorded),'Unrecorded unknown request is not mistaken for recorded history');
 select jsonb_build_object('invoice',(select to_jsonb(i)from public.invoices i where id=invoice),'quote',(select to_jsonb(q)from public.quotes q where id=quote),'order',(select to_jsonb(c)from public.change_orders c where id=change_order),'email',(select md5(coalesce(string_agg(to_jsonb(e)::text,''order by e.id),''))from public.email_events e),'delivery',(select md5(coalesce(string_agg(to_jsonb(d)::text,''order by d.id),''))from app_private.outbound_deliveries d),'queue',(select count(*)from public.customer_communications),'payments',(select count(*)from public.payments))into before_state;
 foreach role_name in array array['owner','admin','estimator','payroll_admin','crew','customer','property_manager','none','disabled','separated','removed']loop
  actor:=gen_random_uuid();insert into auth.users(id,email,raw_user_meta_data)values(actor,'email-history-'||actor||'@example.invalid','{"role":"owner"}');update public.profiles set status=case when role_name='disabled'then 'disabled'else 'active'end where id=actor;insert into public.employee_records(auth_user_id,legal_name,is_active,employment_status)values(actor,'Synthetic history reader',true,'active');if role_name='separated'then update public.employee_records set is_active=false,employment_status='separated'where auth_user_id=actor;end if;
  if role_name not in('none','removed')then insert into public.user_roles(user_id,role_id)select actor,id from public.roles where name=case when role_name in('disabled','separated')then 'owner'else role_name end;end if;
  perform set_config('request.jwt.claim.sub',actor::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated','user_metadata',jsonb_build_object('role','owner'))::text,true);perform set_config('role','authenticated',true);
  for column_name,target,source_table in select * from(values('related_quote_id',quote,'quotes'),('related_invoice_id',invoice,'invoices'),('related_change_order_id',change_order,'change_orders'))r loop
   execute format('select count(*)from public.email_events where %I=$1',column_name)into v using target;
   execute format('select count(*)from public.%I where id=$1',source_table)into source_visible using target;
   perform set_config('role','none',true);perform pg_temp.record_email_check(v=case when role_name in('owner','admin','estimator','payroll_admin')then 2108 else 0 end,column_name||': stored-role/effective-access email visibility '||role_name);perform pg_temp.record_email_check(source_visible=case when role_name in('owner','admin','estimator','payroll_admin')then 1 else 0 end,source_table||': source visibility '||role_name);perform set_config('role','authenticated',true);
  end loop;perform set_config('role','none',true);
 end loop;
 denied:=false;perform set_config('request.jwt.claim.sub','',true);perform set_config('request.jwt.claims','{"role":"anon"}',true);perform set_config('role','anon',true);begin select count(*)into v from public.email_events where related_invoice_id=invoice;denied:=v=0;exception when insufficient_privilege then denied:=true;end;perform set_config('role','none',true);perform pg_temp.record_email_check(denied,'Anonymous email enumeration denied');
 select jsonb_build_object('invoice',(select to_jsonb(i)from public.invoices i where id=invoice),'quote',(select to_jsonb(q)from public.quotes q where id=quote),'order',(select to_jsonb(c)from public.change_orders c where id=change_order),'email',(select md5(coalesce(string_agg(to_jsonb(e)::text,''order by e.id),''))from public.email_events e),'delivery',(select md5(coalesce(string_agg(to_jsonb(d)::text,''order by d.id),''))from app_private.outbound_deliveries d),'queue',(select count(*)from public.customer_communications),'payments',(select count(*)from public.payments))into after_state;
 perform pg_temp.record_email_check(before_state=after_state,'Browsing preserves documents, finances, queue, history and durable deliveries');
 perform pg_temp.record_email_check((select to_jsonb(s)from public.communication_settings s where singleton)=settings_before,'All communication settings unchanged');
end $test$;
select jsonb_build_object('assertions',(select jsonb_agg(label order by label)from pg_temp.record_email_assertions),'sendingSwitchesStayedOff',true)verification;
